with with_windows as (select id, store_id, product_id, quantity, lead(quantity, 1) over (order by last_restock, id) next_quantity, sum(quantity) over (partition by product_id order by last_restock, id rows between unbounded preceding and current row) running_quantity, sum(quantity) over (order by quantity, id rows between unbounded preceding and current row) cumulative_quantity from inventory) select id, store_id, product_id, next_quantity, running_quantity from with_windows
